for cid, targets in [('case_01',{'account_001'}),('case_02',{'account_002','account_9116'})]:
    req=next(r for r in data.sample_requests if r['case_id']==cid); subject=_resolve_case_subject(req,data)
    print('\n',cid,'subject=',subject.user_id,'links=',sorted(subject.linked_resource_ids))
    for rec in corpus.records:
        if rec.resource_id in targets:
            matches=[]
            for name in ('user_id','email','phone','email_hash','name'):
                value=rec.fields.get(name,'')
                if value and any(_contains_identifier(str(value),ident) for ident in subject.identifiers): matches.append(name)
            print(' record=',rec.resource_id,rec.evidence_id,rec.source_component,rec.observed_at,'user_id_match=',rec.fields.get('user_id')==subject.user_id,'identity_fields_matched=',matches,'keys=',sorted(rec.fields))
    link_events=[]
    for ev in data.system_activity:
        if ev.get('event_type','').upper()=='LINK_RESOURCE_IDENTITY' and _contains_identifier(ev.get('details',''),subject.user_id):
            link_events.append((ev['event_time'],ev['resource_id'],ev['activity_id'], ev['event_time']<=req['audit_at']))
    print(' link_events=',link_events)
