expected={r['case_id']:r for r in d.sample_output}
for request in d.sample_requests:
    e=expected[request.case_id]
    a=investigate_case(request,d,c)
    es=json.loads(e['steps_json']); actual=[s.as_dict() if hasattr(s,'as_dict') else s for s in a.steps]
    if es != actual:
        print('\n'+request.case_id, e['deletion_status'], a.status, 'audit_at=', request.audit_at)
        print('expected:')
        for x in es: print(' ',{k:x.get(k) for k in ('phase','system_id','resource_id','operation','state','evidence_id')})
        print('actual:')
        for x in actual: print(' ',{k:x.get(k) for k in ('phase','system_id','resource_id','operation','state','evidence_id')})
