const r = await tools.exec_command({cmd: "@'
import json,sys
from pathlib import Path
sys.path.insert(0,'code')
from data_loading import load_dataset
from evidence import load_evidence
from investigation import investigate_case
root=Path.cwd(); d=load_dataset(root/'dataset'); corpus=load_evidence(d)
expected={r['case_id']:r for r in d.sample_output}
for request in d.sample_requests:
    cid=request['case_id']; e=expected[cid]; p=investigate_case(request,d,corpus)
    es=json.loads(e['steps_json']); ps=[s.as_dict(i) for i,s in enumerate(p.steps,1)]
    if es != ps:
        print('\n'+cid, e['deletion_status']+'>'+p.deletion_status)
        for label, steps in [('E',es),('P',ps)]:
            print(label, '; '.join('/'.join(str(x.get(k,'')) for k in ('phase','system_id','resource_id','operation','state','evidence_id')) for x in steps))
'@ | .venv\Scripts\python.exe -", workdir: "C:\Projects\hackerrank-orchestrate-october26-main\hackerrank-orchestrate-october26-main", max_output_tokens: 5800, yield_time_ms: 30000});
text(r.output);

